package io.github.alreadyonapp.alreadyon

import okhttp3.HttpUrl.Companion.toHttpUrl
import okhttp3.OkHttpClient
import okhttp3.Request
import org.junit.Assert.*
import org.junit.Test
import java.io.File
import java.io.IOException
import java.security.KeyStore
import java.security.cert.X509Certificate
import java.util.Base64
import java.util.concurrent.TimeUnit
import javax.net.ssl.KeyManagerFactory
import javax.net.ssl.SSLContext
import javax.net.ssl.SSLServerSocket
import kotlin.concurrent.thread

// Real TLS handshakes use disposable identities generated by the test JDK.
class ServerTlsTest {
    private fun identity(directory: File, name: String, host: String, expired: Boolean = false): Pair<SSLContext, String> {
        val file = File(directory, "$name.p12")
        val args = mutableListOf(File(System.getProperty("java.home"), "bin/keytool").path,
            "-genkeypair", "-alias", "server", "-keyalg", "RSA", "-keysize", "2048",
            "-storetype", "PKCS12", "-keystore", file.path, "-storepass", "test-password",
            "-dname", "CN=$host", "-ext", "SAN=dns:$host", "-validity", if (expired) "1" else "30", "-noprompt")
        if (expired) args.addAll(listOf("-startdate", "-2d"))
        val process = ProcessBuilder(args).redirectErrorStream(true).start()
        val output = process.inputStream.bufferedReader().readText()
        check(process.waitFor() == 0) { output }
        val store = KeyStore.getInstance("PKCS12").apply { file.inputStream().use { load(it, "test-password".toCharArray()) } }
        val certificate = store.getCertificate("server") as X509Certificate
        val pem = "-----BEGIN CERTIFICATE-----\n" + Base64.getMimeEncoder(64, byteArrayOf(10)).encodeToString(certificate.encoded) + "\n-----END CERTIFICATE-----\n"
        val keys = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm()).apply { init(store, "test-password".toCharArray()) }
        return SSLContext.getInstance("TLS").apply { init(keys.keyManagers, null, null) } to pem
    }

    @Test fun trustComparisonIgnoresFormattingAndOrderButRejectsChangedIdentity() {
        val directory = kotlin.io.path.createTempDirectory("trust-identity").toFile()
        try {
            val first = identity(directory, "first", "one.example").second
            val other = identity(directory, "other", "two.example").second
            assertTrue(sameServerTrust(first, first.replace("\n", "\r\n")))
            assertTrue(sameServerTrust(first + other, other + first))
            assertFalse(sameServerTrust(first, other))
            assertFalse(sameServerTrust(first, first + other))
            assertFalse(sameServerTrust(first, "invalid"))
        } finally { directory.deleteRecursively() }
    }

    private fun request(context: SSLContext, trusted: String?, succeeds: Boolean) {
        val server = context.serverSocketFactory.createServerSocket(0) as SSLServerSocket
        server.soTimeout = 5000
        val worker = thread {
            try {
                server.accept().use { socket ->
                    socket.soTimeout = 5000
                    val input = socket.getInputStream().bufferedReader()
                    while (!input.readLine().isNullOrEmpty()) { /* consume request headers */ }
                    socket.getOutputStream().write("HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\nOK".toByteArray())
                }
            } catch (_: IOException) { /* Expected when client rejects this certificate. */ }
        }
        val origin = "https://localhost:${server.localPort}/".toHttpUrl()
        val client = OkHttpClient.Builder().serverTls(origin, trusted).callTimeout(5, TimeUnit.SECONDS).build()
        try {
            client.newCall(Request.Builder().url(origin).build()).execute().use { response ->
                assertTrue("untrusted server accepted", succeeds)
                assertEquals("OK", response.body!!.string())
            }
        } catch (failure: IOException) {
            if (succeeds) throw failure
        } finally {
            server.close(); worker.join(6000)
            client.connectionPool.evictAll(); client.dispatcher.executorService.shutdown()
        }
    }

    @Test fun onlyCertificateFailuresRequireTrustReview() {
        assertTrue(isServerTrustFailure(javax.net.ssl.SSLHandshakeException("Untrusted chain").apply {
            initCause(java.security.cert.CertificateException("Changed authority"))
        }))
        assertTrue(isServerTrustFailure(IOException(java.security.cert.CertPathValidatorException("Invalid chain"))))
        assertTrue(isServerTrustFailure(javax.net.ssl.SSLPeerUnverifiedException("Unverified peer")))
        assertFalse(isServerTrustFailure(javax.net.ssl.SSLException("Connection reset")))
        assertFalse(isServerTrustFailure(javax.net.ssl.SSLHandshakeException("Peer closed connection")))
        assertFalse(isServerTrustFailure(java.net.ConnectException("Connection refused")))
    }

    @Test fun instanceTrustAcceptsLanNamesAndRejectsOtherAuthorities() {
        val directory = kotlin.io.path.createTempDirectory("tls-test").toFile()
        try {
            val (valid, ca) = identity(directory, "valid", "localhost")
            val (attacker, replacementCa) = identity(directory, "attacker", "localhost")
            val (wrongHost, wrongCa) = identity(directory, "wrong-host", "other.example")
            request(valid, ca, true)
            request(valid, null, false)
            request(attacker, ca, false)
            request(attacker, replacementCa, true) // Explicit replacement restores trust.
            request(wrongHost, wrongCa, true)
            request(wrongHost, null, false)
            val (_, expiredCa) = identity(directory, "expired", "localhost", true)
            try {
                OkHttpClient.Builder().serverTls("https://localhost/".toHttpUrl(), expiredCa)
                fail("Expired trust anchor accepted")
            } catch (_: java.security.cert.CertificateExpiredException) { }
        } finally { directory.deleteRecursively() }
    }

    @Test fun bootstrapRefusesCredentialsAndProtectedRoutes() {
        val origin = "https://localhost:19900/".toHttpUrl()
        val client = OkHttpClient.Builder().bootstrapTls(origin).build()
        try {
            for (request in listOf(
                Request.Builder().url(origin.resolve("/api/auth/status")!!).build(),
                Request.Builder().url(origin.resolve("/api/tv/server")!!).header("Authorization", "Bearer synthetic").build(),
                Request.Builder().url(origin.resolve("/api/tv/trust")!!).header("Cookie", "session=synthetic").build(),
                Request.Builder().url("https://other.example/api/tv/trust").build())) {
                try { client.newCall(request).execute(); fail("Unsafe bootstrap request accepted") }
                catch (failure: IOException) { assertEquals("Only public server metadata is allowed before trust is established.", failure.message) }
            }
        } finally { client.dispatcher.executorService.shutdown() }
    }

    @Test fun instanceCredentialsCannotFollowAnotherOrigin() {
        val directory = kotlin.io.path.createTempDirectory("tls-origin-test").toFile()
        try {
            val (_, ca) = identity(directory, "valid", "localhost")
            val client = OkHttpClient.Builder().serverTls("https://localhost:19900/".toHttpUrl(), ca).build()
            assertFalse(client.followRedirects)
            assertFalse(client.followSslRedirects)
            try {
                client.newCall(Request.Builder().url("https://other.example/").header("Authorization", "Bearer synthetic").build()).execute()
                fail("Other origin accepted")
            } catch (failure: IOException) { assertEquals("Unexpected server origin.", failure.message) }
            finally { client.dispatcher.executorService.shutdown() }
        } finally { directory.deleteRecursively() }
    }
}
